/// KUNIM local database (Drift).
///
/// NOTE: `app_database.g.dart` is generated by
/// `dart run build_runner build --delete-conflicting-outputs` (`make gen`)
/// and is not committed.
library;

import 'package:drift/drift.dart';
import 'package:drift_flutter/drift_flutter.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
// Referenced only from generated code: every [SyncColumns.id] column's
// `clientDefault` (`tables/sync_column_mixin.dart`) is re-emitted by
// `drift_dev` verbatim into `app_database.g.dart`, which is `part of` this
// library — so `Uuid` must be imported here, not just in the mixin's file.
import 'package:uuid/uuid.dart'; // ignore: unused_import

import 'tables/calendar_events_table.dart';
import 'tables/family_logs_table.dart';
import 'tables/goals_table.dart';
import 'tables/habits_table.dart';
import 'tables/health_logs_table.dart';
import 'tables/mood_logs_table.dart';
import 'tables/preferences_table.dart';
import 'tables/sleep_logs_table.dart';
import 'tables/tasks_table.dart';

part 'app_database.g.dart';

/// Outbox for the offline-first sync engine (see `docs/plan.md` section 3).
/// Every local write that must reach the server is appended here in the
/// SAME transaction as the row write itself — a repository must never
/// write a row without also writing its outbox entry.
class SyncOutbox extends Table {
  IntColumn get seq => integer().autoIncrement()();
  TextColumn get entity => text()();
  TextColumn get rowId => text()();
  TextColumn get op => text()();
  TextColumn get payload => text()();
  IntColumn get attempts => integer().withDefault(const Constant(0))();
  TextColumn get lastError => text().nullable()();
  DateTimeColumn get createdAt => dateTime().withDefault(currentDateAndTime)();
}

/// Small generic key/value store for local-only flags and settings that
/// do not warrant their own table (e.g. onboarding completion, last sync
/// cursor before `core/sync` owns it in a later phase).
class KeyValue extends Table {
  TextColumn get key => text()();
  TextColumn get value => text()();

  @override
  Set<Column> get primaryKey => {key};
}

@DriftDatabase(
  tables: [
    SyncOutbox,
    KeyValue,
    Preferences,
    TaskCategories,
    Tasks,
    CalendarEvents,
    Habits,
    HabitLogs,
    Goals,
    Milestones,
    MoodLogs,
    SleepLogs,
    HealthLogs,
    FamilyLogs,
  ],
)
class AppDatabase extends _$AppDatabase {
  AppDatabase() : super(_openConnection());

  /// For tests / DAOs that want to inject a custom executor (e.g. an
  /// in-memory database), per `docs/plan.md` section 13 testing strategy.
  AppDatabase.withExecutor(super.executor);

  @override
  int get schemaVersion => 5;

  /// Version 1 → 2: adds the phase-2 sync tables — `tasks`,
  /// `task_categories`, `calendar_events`, `habits`, `habit_logs`, `goals`,
  /// `milestones` (`docs/plan.md` §3 sync table list). All seven are brand
  /// new tables, so that step is purely additive; nothing existing is
  /// altered or dropped.
  ///
  /// Version 2 → 3: two changes.
  ///
  /// 1. Adds `milestones.progress_percent`. ADR-0002 conflict-matrix rule 18
  ///    names `progress_percent` for `milestones` as well as `goals`, and the
  ///    server's wire row carries it, so a local column is required for the
  ///    row to round-trip.
  /// 2. Replaces `habit_logs`' table-level UNIQUE on the natural key with the
  ///    partial index [_habitLogNaturalKeyIndex], which constrains LIVE rows
  ///    only. See `HabitLogs` for why the table-level constraint made rule 14
  ///    unsatisfiable and deadlocked the pull cursor.
  ///
  /// Version 3 → 4: adds the phase-4 daily log tables `mood_logs`,
  /// `sleep_logs`, `health_logs` and `family_logs`, each with its live-row
  /// natural-key partial index ([_dailyLogNaturalKeyIndex]). Purely additive.
  ///
  /// Version 4 → 5: the `stamp_user_id_*` triggers ([_stampUserIdTrigger])
  /// that give rows inserted while an account is signed in to that account.
  @override
  MigrationStrategy get migration => MigrationStrategy(
        onCreate: (Migrator m) async {
          await m.createAll();
          await customStatement(_habitLogNaturalKeyIndex);
          for (final table in dailyLogTables) {
            await customStatement(_dailyLogNaturalKeyIndex(table));
          }
          for (final table in syncTables) {
            await customStatement(_stampUserIdTrigger(table));
          }
        },
        onUpgrade: (Migrator m, int from, int to) async {
          if (from < 2) {
            await m.createTable(taskCategories);
            await m.createTable(tasks);
            await m.createTable(calendarEvents);
            await m.createTable(habits);
            await m.createTable(habitLogs);
            await m.createTable(goals);
            await m.createTable(milestones);
          }
          if (from < 3) {
            // `from < 2` created these from the CURRENT definitions, which
            // already reflect v3; only a real v2 database needs the changes.
            if (from >= 2) {
              await m.addColumn(milestones, milestones.progressPercent);
              // A UNIQUE table constraint is part of SQLite's CREATE TABLE
              // and cannot be dropped in place, so the table is rebuilt from
              // its current (constraint-free) definition with its rows
              // copied across.
              // `TableMigration` is marked experimental in drift, but it is
              // the only supported way to drop a UNIQUE table constraint;
              // the alternative is hand-written create/copy/drop/rename SQL.
              // ignore: experimental_member_use
              await m.alterTable(TableMigration(habitLogs));
            }
            await customStatement(_habitLogNaturalKeyIndex);
          }
          if (from < 4) {
            await m.createTable(moodLogs);
            await m.createTable(sleepLogs);
            await m.createTable(healthLogs);
            await m.createTable(familyLogs);
            for (final table in dailyLogTables) {
              await customStatement(_dailyLogNaturalKeyIndex(table));
            }
          }
          if (from < 5) {
            // Only tables this install actually has: `preferences` and the
            // sync tables are created by a later phase on some old installs.
            final existing = await customSelect(
              "SELECT name FROM sqlite_master WHERE type = 'table'",
            ).get();
            final names =
                existing.map((row) => row.read<String>('name')).toSet();
            // The triggers read `key_value`; without it they would fail
            // every insert.
            final stampable =
                names.contains('key_value') ? syncTables : const <String>[];
            for (final table in stampable.where(names.contains)) {
              await customStatement(_stampUserIdTrigger(table));
            }
          }
        },
      );

  /// Uniqueness for `habit_logs`' natural key among **live** rows only.
  ///
  /// `deleted_at IS NULL` is the whole point: rule 14's losing row arrives as
  /// a tombstone sharing the natural key, and it has to be storable.
  ///
  /// `COALESCE(user_id, '')` matters just as much: SQLite treats NULLs as
  /// distinct in a UNIQUE index, and `user_id` is NULL for every locally
  /// created row until sign-in exists — so indexing the raw column would
  /// enforce nothing at all today. This mirrors the server's own
  /// `coalesce(ref_id, '')` natural-key convention (ADR-0002 rules 11-13).
  static const String _habitLogNaturalKeyIndex =
      'CREATE UNIQUE INDEX IF NOT EXISTS ux_habit_logs_natural_key '
      "ON habit_logs (COALESCE(user_id, ''), habit_id, date) "
      'WHERE deleted_at IS NULL';

  /// The daily log tables sharing the `(user_id, coalesce(ref_id, ''), date)`
  /// natural key (ADR-0002 rules 11-13 and `family_logs`).
  static const List<String> dailyLogTables = [
    'mood_logs',
    'sleep_logs',
    'health_logs',
    'family_logs',
  ];

  /// Same live-row rule as [_habitLogNaturalKeyIndex], with `ref_id`
  /// coalesced too because it is null for every entry today.
  static String _dailyLogNaturalKeyIndex(String table) =>
      'CREATE UNIQUE INDEX IF NOT EXISTS ux_${table}_natural_key '
      "ON $table (COALESCE(user_id, ''), COALESCE(ref_id, ''), date) "
      'WHERE deleted_at IS NULL';

  /// Every synced table, i.e. every table with `SyncColumns`.
  static const List<String> syncTables = [
    'task_categories',
    'tasks',
    'calendar_events',
    'habits',
    'habit_logs',
    'goals',
    'milestones',
    'preferences',
    'mood_logs',
    'sleep_logs',
    'health_logs',
    'family_logs',
  ];

  /// `key_value` entry holding the signed-in account's user id
  /// (`LocalAccountStore`): present only while an account is signed in.
  static const String accountUserIdKey = 'auth.user_id';

  /// Gives a locally inserted row to the signed-in account.
  ///
  /// Repositories insert rows without a `user_id` (they do not know the
  /// account); while one is signed in, this fills it in, so the natural-key
  /// indexes treat the row exactly like the same account's rows pulled from
  /// the server. Rows that already have an owner (pulled rows) are left
  /// alone, and `OR IGNORE` skips a row that would collide with a live row
  /// of the same natural key instead of failing the user's write.
  static String _stampUserIdTrigger(String table) => '''
CREATE TRIGGER IF NOT EXISTS stamp_user_id_$table
AFTER INSERT ON $table
WHEN NEW.user_id IS NULL
  AND EXISTS (SELECT 1 FROM key_value WHERE "key" = '$accountUserIdKey')
BEGIN
  UPDATE OR IGNORE $table
  SET user_id = (SELECT value FROM key_value WHERE "key" = '$accountUserIdKey')
  WHERE id = NEW.id;
END''';

  static QueryExecutor _openConnection() {
    return driftDatabase(
      name: 'kunim',
      // TODO(Phase-1): supply the SQLCipher encryption key here once
      // `flutter_secure_storage` holds a per-install random key (see
      // docs/plan.md section 11, "SQLCipher, har o'rnatish uchun tasodifiy
      // kalit"). `drift_flutter`'s exact encryption hook API was not
      // verified against a pinned package version in this Phase-0 pass —
      // see PLATFORM-SETUP.md / task risk notes before relying on it.
    );
  }
}

/// Riverpod provider for the single [AppDatabase] instance. Features must
/// depend on DAOs built on top of this, never open their own connection.
final appDatabaseProvider = Provider<AppDatabase>((ref) {
  final db = AppDatabase();
  ref.onDispose(db.close);
  return db;
});
